test_that("MV17-C closure v1 is preserved as rejected historical evidence", {
  root<-testthat::test_path("..","..");a<-file.path(root,"docs","audits","mv17c-calibration-closure-v1");froot<-file.path(root,"docs","audits","mv17c-calibration-closure-v1-rejection-v2");skip_if_not(dir.exists(a)&&dir.exists(froot),"MV17-C rejected closure evidence absent");r<-function(path,n)read.csv(file.path(path,n),stringsAsFactors=FALSE,check.names=FALSE);v<-r(a,"mv17c-validation.csv");e<-r(a,"mv17c-empirical-calibration.csv");d<-r(a,"mv17c-decision.csv");m<-r(a,"mv17c-artifact-manifest.csv");f<-r(froot,"mv17c-time-parser-failure.csv");expect_equal(nrow(v),19L);expect_true(all(v$passed));expect_equal(nrow(e),168L);expect_true(all(e$minimum_attainable_probability==.1));expect_true(d$MV17C_closed);expect_true(d$MV17G_prefreeze_eligible);expect_false(d$full_calibration_authorized);expect_false(any(f$closure_v1_committable));expect_false(any(f$production_rerun_authorized));expect_equal(f$independent_wall_seconds,c(816.83,296.40));files<-file.path(a,m$artifact);expect_equal(as.numeric(file.info(files)$size),m$bytes);hashes<-vapply(files,digest::digest,character(1L),algo="sha256",file=TRUE,serialize=FALSE);expect_equal(unname(hashes),unname(m$sha256))
})

test_that("MV17-C closure v2 is provenance-complete and remains feasibility-only", {
  root<-testthat::test_path("..","..");a<-file.path(root,"docs","audits","mv17c-calibration-closure-v2");skip_if_not(dir.exists(a),"MV17-C closure v2 absent");r<-function(n)read.csv(file.path(a,n),stringsAsFactors=FALSE,check.names=FALSE);v<-r("mv17c-validation.csv");e<-r("mv17c-empirical-calibration.csv");d<-r("mv17c-decision.csv");s<-r("mv17c-resource-summary.csv");b<-r("mv17c-source-binding.csv");m<-r("mv17c-artifact-manifest.csv");expect_equal(nrow(v),21L);expect_true(all(v$passed));expect_equal(nrow(e),168L);expect_true(all(e$minimum_attainable_probability==.1));expect_true(d$MV17C_closed);expect_true(d$MV17G_prefreeze_eligible);expect_false(d$full_calibration_authorized);expect_false(d$production_rerun_performed);expect_equal(s$outer_wall_seconds,c(816.83,296.40));expect_true(all(s$outer_wall_seconds>=s$aggregate_child_seconds));expect_equal(nrow(b),9L);files<-file.path(a,m$artifact);expect_equal(as.numeric(file.info(files)$size),m$bytes);hashes<-vapply(files,digest::digest,character(1L),algo="sha256",file=TRUE,serialize=FALSE);expect_equal(unname(hashes),unname(m$sha256))
})
